import json
import pickle
import base64
import boto3
import hashlib
from datetime import datetime

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table('workflow-state-store')

def lambda_handler(event, context):
    """
    Step Functions task handler that processes workflow state transitions.
    Reads serialized task state from DynamoDB and continues execution.
    """
    workflow_id = event.get('workflow_id')
    task_id = event.get('task_id')
    tenant_id = event.get('tenant_id', 'system')

    # Validate basic input
    if not workflow_id or not task_id:
        return {'statusCode': 400, 'body': 'Missing workflow_id or task_id'}

    # Fetch serialized task state from DynamoDB
    try:
        response = table.get_item(
            Key={
                'pk': f'WORKFLOW#{workflow_id}',
                'sk': f'TASK#{task_id}'
            }
        )
    except Exception as e:
        return {'statusCode': 500, 'body': f'DynamoDB error: {str(e)}'}

    if 'Item' not in response:
        return {'statusCode': 404, 'body': 'Task state not found'}

    item = response['Item']

    # Verify checksum for integrity (NOT security - just corruption detection)
    stored_checksum = item.get('checksum', '')
    payload_bytes = base64.b64decode(item['serialized_state'])
    computed_checksum = hashlib.md5(payload_bytes).hexdigest()

    if stored_checksum and computed_checksum != stored_checksum:
        return {'statusCode': 422, 'body': 'State integrity check failed'}

    # Deserialize the task state to continue workflow execution
    # Using pickle for complex Python objects (custom task definitions)
    task_state = pickle.loads(payload_bytes)

    # Execute the task based on deserialized state
    result = execute_task(task_state, tenant_id)

    # Store result back
    table.put_item(
        Item={
            'pk': f'WORKFLOW#{workflow_id}',
            'sk': f'RESULT#{task_id}',
            'result': json.dumps(result),
            'completed_at': datetime.utcnow().isoformat(),
            'tenant_id': tenant_id
        }
    )

    return {'statusCode': 200, 'body': json.dumps(result)}


def execute_task(task_state, tenant_id):
    """Execute a deserialized task object."""
    if hasattr(task_state, 'run'):
        return task_state.run(tenant_id=tenant_id)
    elif isinstance(task_state, dict):
        action = task_state.get('action')
        params = task_state.get('params', {})
        if action == 'transform':
            return transform_data(params)
        elif action == 'notify':
            return send_notification(params)
        elif action == 'aggregate':
            return aggregate_results(params)
    return {'status': 'no_op'}


def transform_data(params):
    return {'status': 'transformed', 'records': params.get('count', 0)}

def send_notification(params):
    return {'status': 'notified', 'target': params.get('target', 'unknown')}

def aggregate_results(params):
    return {'status': 'aggregated', 'sources': params.get('sources', [])}


